def eval_expression_tree(node):
    """
    Evaluates the given expression tree.

    Args:
        node: The root node of the expression tree.

    Returns:
        The result of evaluating the expression tree.

    Raises:
        ValueError: If the node value is not an integer or a string.

    """
    if not isinstance(node.value, (int, str)):
        raise ValueError("Node value must be an integer or a string.")

    if isinstance(node.value, int):
        return node.value
    else:
        if node.left and node.right:
            left_result = eval_expression_tree(node.left)
            right_result = eval_expression_tree(node.right)
            if node.value == '+':
                return left_result + right_result
            elif node.value == '-':
                return left_result - right_result
            elif node.value == '*':
                return left_result * right_result
            elif node.value == '/':
                return left_result / right_result
            else:
                raise ValueError("Invalid operator.")
        elif node.left:
            return eval_expression_tree(node.left)
        elif node.right:
            return eval_expression_tree(node.right)
        else:
            return 0

